// Normaliza correos y deduplica contra las filas existentes leídas de Google Sheets
const gmailMessages = $('Gmail Search Historical Payrolls').all();
let existingSheetItems = [];
try {
  existingSheetItems = $('Get Existing Control_Aprobacion Rows').all();
} catch (e) {
  existingSheetItems = [];
}

const existingIds = new Set();
for (const item of existingSheetItems) {
  const row = item.json || {};
  if (row.ID_Mensaje && !item.json.error) {
    existingIds.add(String(row.ID_Mensaje).trim());
  }
}

function formatSender(raw) {
  if (!raw) return '';
  if (typeof raw === 'string') return raw;
  if (typeof raw === 'object') {
    if (raw.text) return String(raw.text);
    if (raw.value && Array.isArray(raw.value) && raw.value.length > 0) {
      const v = raw.value[0];
      return v.name ? `${v.name} <${v.address}>` : (v.address || '');
    }
    if (raw.name && raw.address) return `${raw.name} <${raw.address}>`;
    if (raw.address) return String(raw.address);
    if (raw.name) return String(raw.name);
    if (raw.email) return String(raw.email);
  }
  return String(raw);
}

function extractHeader(msg, key) {
  const target = key.toLowerCase();

  // 1. Cabeceras en msg.payload.headers (Gmail API estándar)
  if (msg.payload && Array.isArray(msg.payload.headers)) {
    const found = msg.payload.headers.find(h => h && h.name && h.name.toLowerCase() === target);
    if (found && found.value) return found.value;
  }

  // 2. Cabeceras en msg.headers
  if (msg.headers && typeof msg.headers === 'object') {
    if (Array.isArray(msg.headers)) {
      const found = msg.headers.find(h => h && h.name && h.name.toLowerCase() === target);
      if (found && found.value) return found.value;
    } else {
      for (const [k, v] of Object.entries(msg.headers)) {
        if (k.toLowerCase() === target) return typeof v === 'object' ? formatSender(v) : String(v);
      }
    }
  }

  // 3. Propiedad de primer nivel
  if (msg[target] !== undefined) return typeof msg[target] === 'object' ? formatSender(msg[target]) : String(msg[target]);

  return '';
}

function findAttachments(msg) {
  const list = [];

  // A. attachments planos de n8n
  if (Array.isArray(msg.attachments)) {
    for (const a of msg.attachments) {
      const name = a.filename || a.name || '';
      if (name) {
        list.push({
          id: a.id || a.attachmentId || (a.body && a.body.attachmentId) || msg.id,
          filename: name
        });
      }
    }
  }

  // B. Recorrido recursivo en payload.parts
  function walk(parts) {
    if (!parts || !Array.isArray(parts)) return;
    for (const p of parts) {
      const fn = p.filename || p.name || '';
      const attId = p.body ? (p.body.attachmentId || p.body.id) : null;
      if (fn) {
        list.push({
          id: attId || p.partId || msg.id,
          filename: fn
        });
      }
      if (p.parts && Array.isArray(p.parts)) {
        walk(p.parts);
      }
    }
  }

  if (msg.payload) {
    if (msg.payload.filename) {
      list.push({
        id: (msg.payload.body && msg.payload.body.attachmentId) || msg.id,
        filename: msg.payload.filename
      });
    }
    if (msg.payload.parts) {
      walk(msg.payload.parts);
    }
  }

  return list;
}

const newRows = [];
for (const msgItem of gmailMessages) {
  const msg = msgItem.json || {};
  const messageId = String(msg.id || msg.threadId || '').trim();
  if (!messageId || existingIds.has(messageId)) continue;

  let dateStr = '';
  if (msg.internalDate) {
    try { dateStr = new Date(parseInt(msg.internalDate)).toISOString().split('T')[0]; } catch (e) {}
  }
  if (!dateStr) dateStr = extractHeader(msg, 'date') || msg.date || new Date().toISOString().split('T')[0];

  const from = extractHeader(msg, 'from') || 'Gestoría';
  const subject = extractHeader(msg, 'subject') || 'Envío Hojas de Salario';

  const discoveredAttachments = findAttachments(msg);
  // Filtrar ficheros .zip o tomar el primero si no hay extensión explícita
  const zipAttachments = discoveredAttachments.filter(a => a.filename.toLowerCase().endsWith('.zip'));
  const targetAttachments = zipAttachments.length > 0 ? zipAttachments : (discoveredAttachments.length > 0 ? discoveredAttachments : [{
    id: messageId,
    filename: 'Nomina.zip'
  }]);

  for (const att of targetAttachments) {
    existingIds.add(messageId);
    newRows.push({
      json: {
        ID_Mensaje: messageId,
        Fecha_Correo: dateStr,
        Remitente: from,
        Asunto: subject,
        Nombre_Adjunto: att.filename,
        ID_Adjunto: att.id,
        Aprobado: false,
        Procesado: false
      }
    });
  }
}

return newRows;
